-- Step 1: Find the audit log entries for cmd.exe that started dumpcap.exe
SELECT time, pid, ppid, pname, process_name, command_line, parent_process_name, parent_process_path, parent_command_line
FROM audit_logs
WHERE pname = 'cmd.exe' AND pid IN (
    SELECT ppid FROM audit_logs WHERE pname = 'dumpcap.exe'
) ORDER BY time ASC;

